class Solution {
public:
    vector<int> countArrayPairs(vector<int>& A, vector<int>& B) {
        const long long MOD = 1000000007; int top = 0;
        for (size_t i = 0; i < A.size(); i++) top = max(top, B[i] + 2 * A[i]);
        vector<long long> f(top + 1, 1), inv(top + 1, 1);
        for (int i = 1; i <= top; i++) f[i] = f[i - 1] * i % MOD;
        auto pw = [&](long long b, long long e) { long long r = 1; b %= MOD; while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; } return r; };
        inv[top] = pw(f[top], MOD - 2);
        for (int i = top; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
        vector<int> res;
        for (size_t i = 0; i < A.size(); i++) { int n = A[i], m = B[i]; res.push_back(f[m + 2 * n - 1] * inv[2 * n] % MOD * inv[m - 1] % MOD); }
        return res;
    }
};

